10	/// Returns true if subtree changes application state.
11	///
12	/// This trait assumes the following:
13	/// - `.toString()`, `.valueOf()`, and `[Symbol.toPrimitive]()` are side-effect free.
14	///   - This is mainly to assume `ToPrimitive` is side-effect free.
15	///   - Note that the builtin `Array::toString` has a side-effect when a value contains a Symbol as `ToString(Symbol)` throws an error. Maybe we should revisit this assumption and remove it.
16	///     - For example, `"" == [Symbol()]` returns an error, but this trait returns `false`.
17	/// - Errors thrown when creating a String or an Array that exceeds the maximum length does not happen.
18	/// - TDZ errors does not happen.
19	///
20	/// Ported from [closure-compiler](https://github.com/google/closure-compiler/blob/f3ce5ed8b630428e311fe9aa2e20d36560d975e2/src/com/google/javascript/jscomp/AstAnalyzer.java#L94)
21	pub trait MayHaveSideEffects<'a> {
22	    fn may_have_side_effects(&self, ctx: &impl MayHaveSideEffectsContext<'a>) -> bool;
23	}
24	
25	impl<'a, T: MayHaveSideEffects<'a>> MayHaveSideEffects<'a> for Option<T> {
26	    fn may_have_side_effects(&self, ctx: &impl MayHaveSideEffectsContext<'a>) -> bool {
27	        self.as_ref().is_some_and(|t| t.may_have_side_effects(ctx))
28	    }
29	}
