/// Whether reading the global identifier with the given `name` is known to be side-effect free.
///
/// This includes well-known builtin objects/functions (which are safe regardless of
/// configuration) as well as commonly used environment globals (`console`, `document`,
/// `window`, `fetch`) which are only treated as safe when they are declared as global variables.
#[rustfmt::skip]
fn is_side_effect_free_global(name: &str) -> bool {
    matches!(name,
